function encodedPath(path) {
  return path.split("/").map(encodeURIComponent).join("/");
}

function sameImageSource(image, source) {
  try {
    const a = decodeURIComponent(new URL(image.currentSrc || image.src, window.location.href).pathname).toLowerCase();
    const b = decodeURIComponent(new URL(source, window.location.href).pathname).toLowerCase();
    return a === b;
  } catch {
    return false;
  }
}

function ensureGalleryStyles() {
  if (document.getElementById("ec-bulk-photo-gallery-styles")) return;
  const style = document.createElement("style");
  style.id = "ec-bulk-photo-gallery-styles";
  style.textContent = ".ec-bulk-photo-gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:16px;margin:32px auto}.ec-bulk-photo-item{margin:0;min-width:0}.ec-bulk-photo-item img{display:block;width:100%;height:auto;max-height:480px;object-fit:contain;border-radius:16px;background:#f6f0e6}@media(max-width:600px){.ec-bulk-photo-gallery{grid-template-columns:repeat(auto-fit,minmax(min(100%,155px),1fr));gap:10px;margin:22px auto}.ec-bulk-photo-item img{border-radius:12px}}";
  document.head.append(style);
}

export function addBulkPhotoReferences() {
  let pathname = window.location.pathname;
  while (pathname.endsWith("/")) pathname = pathname.slice(0, -1);
  const route = Object.keys(PHOTO_PATHS_BY_ROUTE).find((candidate) => pathname.endsWith(candidate));
  if (!route || document.querySelector("[data-bulk-photo-reference-route]")) return;
  const main = document.querySelector("main") || document.body;
  const photos = PHOTO_PATHS_BY_ROUTE[route];
  const missing = photos.filter((path) => {
    const source = `${HOST}/${encodedPath(path)}`;
    return ![...document.images].some((image) => sameImageSource(image, source));
  });
  if (!missing.length) return;
  ensureGalleryStyles();
  const gallery = document.createElement("section");
  gallery.className = "ec-bulk-photo-gallery";
  gallery.dataset.bulkPhotoReferenceRoute = route;
  gallery.setAttribute("role", "group");
  const heading = document.querySelector("main h1")?.textContent?.trim() || route.split("/").pop().replace(/-/g, " ");
  gallery.setAttribute("aria-label", `Fotos de ${heading}`);
  for (const path of missing) {
    const figure = document.createElement("figure");
    figure.className = "ec-bulk-photo-item";
    const image = document.createElement("img");
    image.src = `${HOST}/${encodedPath(path)}`;
    const filename = path.split("/").pop().split(".").slice(0, -1).join(".").replaceAll("_", " ").replaceAll("-", " ");
    image.alt = `${heading}: ${filename}`;
    image.loading = "lazy";
    image.decoding = "async";
    figure.append(image);
    gallery.append(figure);
  }
  main.append(gallery);
}
